import { timingSafeEqual, createHash } from 'node:crypto';
import { pool } from '../../lib/db.js';
import { requireUser, json } from '../../lib/access.js';
export async function POST(request){const c=await requireUser(request);if(c.response)return c.response;const mail=String(process.env.MAXWEB_INITIAL_ADMIN_EMAIL||'').trim().toLowerCase(),expected=String(process.env.MAXWEB_INITIAL_ADMIN_TOKEN||''),b=await request.json().catch(()=>null),given=String(b?.token||'');if(!mail||expected.length<32)return json({error:'bootstrap_not_configured'},503);const a=createHash('sha256').update(expected).digest(),z=createHash('sha256').update(given).digest();if(!timingSafeEqual(a,z)||String(c.user.email||'').toLowerCase()!==mail)return json({error:'not_authorised'},403);const db=await pool.connect();try{await db.query('BEGIN');const n=await db.query("SELECT count(*)::int AS count FROM public.maxweb_profiles WHERE role IN ('admin','super_admin')");if(n.rows[0].count){await db.query('ROLLBACK');return json({error:'bootstrap_already_claimed'},409);}await db.query("UPDATE public.maxweb_profiles SET role='super_admin',updated_at=now() WHERE user_id=$1",[c.user.id]);await db.query("INSERT INTO public.maxweb_audit_logs(actor_user_id,action,entity_type,entity_id) VALUES($1,'initial_admin.claimed','profile',$1)",[c.user.id]);await db.query('COMMIT');return json({accepted:true,role:'super_admin'});}catch(e){await db.query('ROLLBACK').catch(()=>{});console.error(e?.message);return json({error:'server_error'},500);}finally{db.release();}}
